use std::pin::Pin;
fn main() {
    let mut text = String::from("crab");
    let pinned = Pin::new(&mut text);
    let moved = std::mem::take(Pin::into_inner(pinned));
    assert_eq!(moved, "crab");
    assert!(text.is_empty());
    println!("Unpin permits the move: {moved}");
}

